import { Vector3 } from './Vector3.js';
export class Plane {
    constant;
    normal = new Vector3(1, 0, 0);
    constructor(normal, constant = 0) {
        this.constant = constant;
        if (normal)
            this.normal.copy(normal);
    }
    setComponents(x, y, z, constant) { this.normal.set(x, y, z); this.constant = constant; return this; }
    normalize() { const inverse = 1 / this.normal.length(); this.normal.multiplyScalar(inverse); this.constant *= inverse; return this; }
    distanceToPoint(point) { return this.normal.dot(point) + this.constant; }
}